import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";import"./0007-DRt9Epfj.js";import"./0014-CAOFrlLX.js";var i=JSON.parse(`{"path":"/MarkovDecisionProcess.html","title":"MarkovDecisionProcess","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":2.03,"words":610},"filePathRelative":"MarkovDecisionProcess.md"}`),a={name:`MarkovDecisionProcess.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="markovdecisionprocess" tabindex="-1"><a class="header-anchor" href="#markovdecisionprocess"><span>MarkovDecisionProcess</span></a></h1><p><a href="./強化学習.html">強化学習</a>で良く扱う過程。マルコフ性については<a href="./強化学習の用語定義.html">強化学習の用語定義</a>参照。</p><ul><li><a href="https://www.youtube.com/watch?v=WsvFL-LjA6U" target="_blank" rel="noopener noreferrer">Stanford CS234 Reinforcement Learning I Introduction to Reinforcement Learning I 2024 I Lecture 1 - YouTube</a></li><li><a href="https://www.youtube.com/watch?v=gHdsUUGcBC0&amp;list=PLoROMvodv4rN4wG6Nk6sNpTEbuOSosZdX&amp;index=3" target="_blank" rel="noopener noreferrer">Stanford CS234 Reinforcement Learning I Tabular MDP Planning I 2024 I Lecture 2 - YouTube</a></li></ul><h2 id="mdpの定義" tabindex="-1"><a class="header-anchor" href="#mdpの定義"><span>MDPの定義</span></a></h2><p><a href="./強化学習の用語定義.html">強化学習の用語定義</a>にあるSequential Decision Processのうち、マルコフassumptionの成り立つもの。</p><h2 id="mdpの例" tabindex="-1"><a class="header-anchor" href="#mdpの例"><span>MDPの例</span></a></h2><p><img src="/RandomThoughts/assets/0006-CgG6-JSP.png" alt="imgs/CS234Intro/0006.png"></p><h2 id="markov-reward-process-mrp" tabindex="-1"><a class="header-anchor" href="#markov-reward-process-mrp"><span>Markov Reward Process (MRP)</span></a></h2><p><img src="/RandomThoughts/assets/0009-Cnw5EYm7.png" alt="imgs/CS234Intro/0009.png"></p><h2 id="無限地平でのmrp" tabindex="-1"><a class="header-anchor" href="#無限地平でのmrp"><span>無限地平でのMRP</span></a></h2><p><img src="/RandomThoughts/assets/0000-UEMRykr5.png" alt="imgs/CS234Lec2/0000.png"></p><h3 id="vを求める-dpによるiterativeな算出" tabindex="-1"><a class="header-anchor" href="#vを求める-dpによるiterativeな算出"><span>Vを求める（DPによるiterativeな算出）</span></a></h3><p>Value State関数を求める。<a href="./Value関数.html">Value関数</a>。</p><p><img src="/RandomThoughts/assets/0001-BVO5WX1J.png" alt="imgs/CS234Lec2/0001.png"></p><h2 id="無限地平のmdp" tabindex="-1"><a class="header-anchor" href="#無限地平のmdp"><span>無限地平のMDP</span></a></h2><p>MRPはMDP+actionなので前のMRPの続きとしてMDPを考える。</p><p><img src="/RandomThoughts/assets/0002-BbNEeYZE.png" alt="imgs/CS234Lec2/0002.png"></p><h3 id="ポリシーを足すとmrpになる" tabindex="-1"><a class="header-anchor" href="#ポリシーを足すとmrpになる"><span>ポリシーを足すとMRPになる</span></a></h3><p><img src="/RandomThoughts/assets/0003-DkN-CyrT.png" alt="imgs/CS234Lec2/0003.png"></p><p>ポリシーを足すとRとPにそれを取り込む事が出来て、そうしたRとPを持つMRPと考える事が出来る。 すろと先に見たVの算出方法が使える。</p><h3 id="ポリシーの評価" tabindex="-1"><a class="header-anchor" href="#ポリシーの評価"><span>ポリシーの評価</span></a></h3><p>あるポリシーがどのくらい良いものか、という事を評価するには、Vを求めれば良い。</p><p><img src="/RandomThoughts/assets/0004-D92Cd8kY.png" alt="imgs/CS234Lec2/0004.png"></p><h3 id="最適なポリシーを求める-mdp-control-ための前準備" tabindex="-1"><a class="header-anchor" href="#最適なポリシーを求める-mdp-control-ための前準備"><span>最適なポリシーを求める（MDP Control）ための前準備</span></a></h3><p>あるポリシーがどのくらい良いか、という評価の方法は分かった。 次に最適なポリシーを探索する方法を考える。</p><p>実際の計算に入る前に、以下の二つの事実を考慮に入れておくと良い（後で証明する）</p><p>無限地平のMDPでは、</p><ul><li>最適なVがユニークに存在する</li><li>最適なポリシーはdeterministicになる。</li></ul><p><img src="/RandomThoughts/assets/0005-KzO0noV0.png" alt="imgs/CS234Lec2/0005.png"></p><h3 id="policy-iteration-pi" tabindex="-1"><a class="header-anchor" href="#policy-iteration-pi"><span>Policy Iteration（PI）</span></a></h3><p>最適なポリシーをPIで求める。</p><p><img src="/RandomThoughts/assets/0006-KrSLB7Sg.png" alt="imgs/CS234Lec2/0006.png"></p><p>このPolicy improvementについて以下に見ていく。</p><h3 id="q関数" tabindex="-1"><a class="header-anchor" href="#q関数"><span>Q関数</span></a></h3><p><img src="/RandomThoughts/assets/0007-DNhUrNP2.png" alt="imgs/CS234Lec2/0007.png"></p><p><a href="./Q関数.html">Q関数</a></p><h3 id="policy-improvementの手順" tabindex="-1"><a class="header-anchor" href="#policy-improvementの手順"><span>Policy Improvementの手順</span></a></h3><p><img src="/RandomThoughts/assets/0008-DIdFmbXw.png" alt="imgs/CS234Lec2/0008.png"></p><h3 id="policy-improvementは実際に何をやっているか" tabindex="-1"><a class="header-anchor" href="#policy-improvementは実際に何をやっているか"><span>Policy Improvementは実際に何をやっているか？</span></a></h3><p><img src="/RandomThoughts/assets/0009-Cmf3MF3S.png" alt="imgs/CS234Lec2/0009.png"></p><p>各sに対し、一つアクションをaに置き換えて、以後は前のポリシーに従うとVが改善する、というようなaを求めている訳だ。</p><p>このsに対して一回なら改善すると分かっているaのマッピングを全てのポリシーとして扱う、というのがPolicy Improvementの手続きとなる。</p><p>それは改善になっているのか？という疑問を見ていく。</p><h3 id="policyのmonotonic-improvement" tabindex="-1"><a class="header-anchor" href="#policyのmonotonic-improvement"><span>PolicyのMonotonic Improvement</span></a></h3><p>この手順がVを単調に改善していく、という事実を見ていく。</p><p><img src="/RandomThoughts/assets/0010-CiO1fQj8.png" alt="imgs/CS234Lec2/0010.png"><img src="/RandomThoughts/assets/0011-Bv5n_W50.png" alt="imgs/CS234Lec2/0011.png"></p><p>つまり、一つのアクションだけだとQが改善するという時に、 この残った前のポリシーのVをさらに新しいactionのQで上から抑えてそれを展開すると同じ形になるので、 再帰的にこの操作を繰り返してどんどん未来のポリシーを置き換えていける。</p><p>割引率で将来は消えるのだから、間の残った項だけを見ると、これが新しいポリシーでのVとなっている。 上から抑えた結果が新しいポリシーなので、新しいポリシーの方が上となる。</p><p>等号は全てのQのargmaxが元のポリシーと同じ場合のみで、それは既にVが最適なケースとなる。</p><h3 id="bellmanのバックアップ演算子" tabindex="-1"><a class="header-anchor" href="#bellmanのバックアップ演算子"><span>Bellmanのバックアップ演算子</span></a></h3><p>次に最適なVを求めるという問題を考えるにあたり、下準備としてBellmanのBackup Operatorを定義する。</p><p><a href="./ベルマンバックアップ演算子.html">ベルマンバックアップ演算子</a></p><h3 id="value-iterationによる最適なvの計算" tabindex="-1"><a class="header-anchor" href="#value-iterationによる最適なvの計算"><span>Value Iterationによる最適なVの計算</span></a></h3><p><img src="/RandomThoughts/assets/0013-nLHXHhsG.png" alt="imgs/CS234Lec2/0013.png"></p><p>初期化したVから始めてバックアップ演算子を収束するまで延々と適用し続けていけば良い。</p><p>バックアップ演算子は最適なaを探す操作を含むので、最適なVが出た後に一回同じ操作で最適なaを各sについて探していけば最適なポリシーも得られる。</p><h3 id="viが最適な解を得られる証明" tabindex="-1"><a class="header-anchor" href="#viが最適な解を得られる証明"><span>VIが最適な解を得られる証明</span></a></h3><p><img src="/RandomThoughts/assets/0015-jatXq9F4.png" alt="imgs/CS234Lec2/0015.png"><img src="/RandomThoughts/assets/0016-Bv0qzkWI.png" alt="imgs/CS234Lec2/0016.png"></p><h3 id="piをバックアップ演算子で考える" tabindex="-1"><a class="header-anchor" href="#piをバックアップ演算子で考える"><span>PIをバックアップ演算子で考える</span></a></h3><p><img src="/RandomThoughts/assets/0014-CFHKTKX1.png" alt="imgs/CS234Lec2/0014.png"></p><p>あるポリシーに対するバックアップ演算子を定義して、それを繰り返し適用する、という話。</p><p>一回適用すると１期のポリシーに従った時の利得と、それ以後の初期に与えられたVの利得、という計算になる。 これをN期までやればN期までポリシーに従った利得となり、 無限に繰り返せばポリシーに従った<a href="./Value関数.html">Value関数</a>になるという事か。</p><p>ポリシーに対応したValue関数を得るというのはそのポリシーの評価の所でやった話と合流する。</p><p>ポリシーに対するValue関数が得られれば、１期分だけValueを改善するactionを探す、 この時、以後のValueを得られているポリシーのValueで計算出来る、というのがポイント。</p><p>これで１期分だけ改善するactionを各sについて求める事が出来、これを新しいポリシーとする事が出来る（Policy Improvement)</p><h2 id="有限地平の場合" tabindex="-1"><a class="header-anchor" href="#有限地平の場合"><span>有限地平の場合</span></a></h2><p><img src="/RandomThoughts/assets/0017-COmomAEI.png" alt="imgs/CS234Lec2/0017.png"></p><h3 id="valueをシミュレーションで求める" tabindex="-1"><a class="header-anchor" href="#valueをシミュレーションで求める"><span>Valueをシミュレーションで求める</span></a></h3><p>有限地平の場合、ポリシーからエピソードを複数生成する事が簡単に出来る場合がある。 その場合はエピソードを複数生成してリターンを計算して平均してしまえば、直接Vの推計値を得る事が出来てしまう。</p><p><img src="/RandomThoughts/assets/0018-DZ0VB_oy.png" alt="imgs/CS234Lec2/0018.png"></p>`,70)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};